enum ErroBancario: Error {
    case saldoInsuficiente
    case limiteDiarioExcedido
    case contaBloqueada
}

func sacar(valor: Double, saldo: Double) throws -> Double {
    guard valor <= saldo else {
        throw ErroBancario.saldoInsuficiente
    }
    return saldo - valor
}

do {
    let novoSaldo = try sacar(valor: 100, saldo: 50)
    print("Saque efetuado. Saldo: \(novoSaldo)")
} catch ErroBancario.saldoInsuficiente {
    print("Você não tem dinheiro suficiente.")
} catch {
    print("Erro desconhecido: \(error)")
}

