}

actor ContaBancaria {
    var saldo: Double = 0
    // Este método é thread-safe
    func depositar(_ valor: Double) {
        saldo += valor
    }
}

func buscarFotos() async -> [String] {
    return await withTaskGroup(of: String.self) { group in
        group.addTask { await processar("img1") }
        group.addTask { await processar("img2") }
        var results = [String]()
        for await res in group { results.append(res) }
        return results
    }
}

